Matching Ayahs
- = 艾利夫，俩目，米目。2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = 这些人，是遵守他们的主的正道的; 这些人，确是成功的。2:5; 31:5
- = 以色列的后裔啊！你们当铭记我所赐你们的恩惠，并铭记我曾使你们超越世人。2:47; 2:122
- = 那是一个已逝去的民族，他们将获得他们所营谋的，你们也将获得你们所营谋的，你们对他们的行为不负责任。2:134; 2:141
- = 他们将永居其中，刑罚不减轻他们，他们也不被宽限。2:162; 3:88
- = 惟在那之后悔过自新的人除外，安拉确是至赦的，确是至慈的。3:89; 24:5
- = 不信道且否认我的迹象的人，是火狱的居民。5:10; 5:86
- = 只要他们的主的一项迹象降临他们，他们总是背弃它。6:4; 36:46
- = 在你之前，有许多使者确已被人嘲笑，但嘲笑者终为自己的嘲弄所包围。6:10; 21:41
- = 你说：“如果我违抗我的主，我确畏惧重大日的刑罚。”6:15; 39:13
- = 于是地震袭击了他们，他们僵卧在自己的家中。7:78; 7:91
- = 他就扔下他的手杖，那手杖忽然变成一条明显的大蛇。7:107; 26:32
- = 他抽出他的手来，那手在观看者眼中忽然显出白光。7:108; 26:33
- = 他们说：“我们已信仰众世界的主。”7:121; 26:47
- = 穆萨和哈伦的主。7:122; 26:48
- = 我将宽限他们，我的计策确是周密的。7:183; 68:45
- = 他因正道和真教而派遣他的使者，以便他使真教胜过一切宗教，即使以物配主者不愿意。9:33; 61:9
- = 先知啊！你当对不信道者和伪信者战斗并严厉对待他们，他们的归宿是火狱，那归宿真恶劣！9:73; 66:9
- = 他们说：“这个警告何时实现呢？如果你们是诚实的人。”10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = 我确已派遣穆萨带着我的迹象和明证去。11:96; 40:23
- = 我确已把经典赐给穆萨，但人们对它产生分歧。若非你的主预先说过一句话，他们间必受判决。他们对于它确是在不安的怀疑中。11:110; 41:45
- = 这对于安拉不是难事。14:20; 35:17
- = “当我把他塑造成，并把我的精神吹入他的时候，你们应当向他俯伏叩头。”15:29; 38:72
- = 众天使全体一同叩头。15:30; 38:73
- = 主说：“你从这里出去吧！因为你确是被驱逐的。”15:34; 38:77
- = 他说：“我的主啊！求你宽限我到他们被复活之日。”15:36; 38:79
- = 主说：“你确是被宽限的。”15:37; 38:80
- = 直到被规定的时候之日。15:38; 38:81
- = 惟他们中你所选拔的仆人除外。15:40; 38:83
- = 敬畏者必在乐园和泉源之间。15:45; 51:15
- = 他说：“诸位使者啊！你们有什么差事呢？”15:57; 51:31
- = 他们说：“我们确是被派往一群犯罪的民众。”15:58; 51:32
- = 信道而不以不义混淆其信德的人，他们得享安宁，他们是遵循正道的。16:42; 29:59
- = 以至辜负我所赐予他们的恩惠。你们享受吧，不久你们就会知道。16:55; 30:34
- = 然后他走上一条道路。18:89; 18:92
- = 你去见法老，他确是暴虐无道的。20:24; 79:17
- = 他们是保守贞操的。23:5; 70:29
- = 除非对他们的妻子或他们的奴婢，他们确是不受责备的。23:6; 70:30
- = 此外有所求的人，都是过分的人。23:7; 70:31
- = 他们是尊重所受的信托和所缔的盟约的。23:8; 70:32
- = 他说：“我的主啊！求你援助我，因为他们已否认我了。”23:26; 23:39
- = 塔，辛，米目。26:1; 28:1
- = 这是明确的经典的节文。26:2; 28:2
- = 其中确有一种迹象，但他们大半不信。26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = 你的主确是万能的，确是至慈的。26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = 然后，我淹死了其余的人。26:66; 37:82
- = 我对于你们确是一个忠实的使者。26:107; 26:125; 26:143; 26:162; 26:178
- = 故你们应当敬畏安拉，应当服从我。26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = 我不为传达使命而向你们索取任何报酬; 我的报酬只由众世界的主负担。26:109; 26:127; 26:145; 26:164; 26:180
- = 在园圃和泉源之间。26:147; 44:52
- = 他们说：“你只是被迷惑的人之一。”26:153; 26:185
- = 但她的妻子除外——我已预定她属于留下的人。26:171; 37:135
- = 然后我毁灭了其余的人。26:172; 37:136
- = 我降石雨给他们，被警告者的雨真恶劣！26:173; 27:58
- = 难道他们要求我的刑罚早日实现吗？26:204; 37:176
- = 他们谨守拜功，完纳天课，并确信后世。27:3; 31:4
- = 在那日，他将召唤他们，说：“你们所妄称的我的伙伴在哪里呢？”28:62; 28:74
- = 以及我们的祖先呢？37:17; 56:48
- = 他们互相走近，互相询问。37:27; 52:25
- = 唯安拉的虔诚的仆人不在此列。37:40; 37:74; 37:128; 37:160
- = 在恩泽的乐园中。37:43; 56:12
- = 我使他的令名永存于后代之中。37:78; 37:108; 37:129
- = 我必定这样报酬行善的人。37:80; 37:121; 37:131; 77:44
- = 他确是我的信道的仆人之一。37:81; 37:111; 37:132
- = 你们有什么理由？你们怎么判断呢？37:154; 68:36
- = 这《古兰经》只是对众世界的一个教诲。38:87; 81:27
- = 这部经典的降示来自万能的、至睿的安拉。39:1; 45:2; 46:2
- = 哈，米目。40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = 以明确的经典盟誓。43:2; 44:2
- = 你让他们妄谈和游戏吧！直到他们遇见他们被警告的日子。43:83; 70:42
- = （他们将被告知：）“你们因自己的行为而愉快地吃喝吧！”52:19; 77:43
- = 难道你向他们索取报酬，因而他们为债务而负担过重吗？52:40; 68:46
- = 难道他们能知幽玄，故能把它记录下来吗？52:41; 68:47
- = 我的刑罚和警告是怎样的！54:16; 54:21; 54:30
- = 我确已使《古兰经》易于记诵，有接受劝告的人吗？54:17; 54:22; 54:32; 54:40
- = 你们究竟否认你们的主的哪一项恩典呢？55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = 许多前人。56:13; 56:39
- = 不然，我们是被剥夺的。56:67; 68:27
- = 故你当颂扬你的主的大名。56:74; 56:96; 69:52
- = 这是从众世界的主降示的。56:80; 69:43
- = 天地万物都赞颂安拉超绝万物，他确是万能的，确是至睿的。59:1; 61:1
- = 有人向他宣读我的迹象时，他便说：“这是古人的神话。”68:15; 83:13
- = 他将在愉快的生活中。69:21; 101:7
- = 在高高的乐园中。69:22; 88:10
- = 且不勉励人赈济贫民。69:34; 107:3
- = 《古兰经》确是一位尊贵使者的言辞。69:40; 81:19
- = 这确是一种教诲。谁愿意，谁就可以择取一条通向他的主的道路。73:19; 76:29
