- 当他们遇见信士们的时候，他们说：我们已信道了；当他们私下相聚的时候。 (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- 他们谨守《讨拉特》和《引支勒》，以及他们的主所降示的。 (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- 他知道他们面前的事和他们身后的事，他们不能包罗他的知识。 (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- 他是在六日内创造天地万物的主。 (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- 此中确有一种迹象，如果你们是信士。 (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- 当正道来临众人时，什么阻止他们信道呢？ (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- 他们为安拉树立许多匹敌，以便使人背离主道。你说：你们享受吧。 (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- 他们诧异，因为他们同族中的一个警告者来临他们，不信道的人们说：这是。 (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- 你的主确是最知道谁迷误的。 (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- 犹如那为了向人炫耀而施舍财产，并不信安拉的人。 (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- 在那一日来临之前，你们当分舍我所赐予你们的。 (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- 他为你们制服了天地万物。 (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- 我们对于你所召我们的确在不安的怀疑中。 (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- 你的主的确使他所欲者给养宽裕，或使给养窘迫。他确。 (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- 他是天地万物的主，如果你们是确信者。 (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- 我们确信安拉，确信我们所受的启示，与易卜拉欣、易司马仪、易司哈格、叶尔孤白和各支派所受的启示。 (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- 不义者被一声巨响袭击，他们在自己的家里僵卧着。 (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- 她们为自身所做的事，你们毫无罪过。 (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- 你的主最知道谁迷误的，他。 (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- 他依自己的命令把精神（启示）降给他所意欲的仆人。 (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- 我确已赐给麦尔彦之子尔撒明证，并以圣灵扶助他。 (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- 复活日他必将为他们判决他们所分歧的。 (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- 我把那个市镇天翻地覆，并使烧过的粘土石像雨点般降落在他们身上。 (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- 你对他们加以警告与否，他们是一样的，他们不信道。 (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- 除人类外，如果你们是诚实的，你们就希望死亡吧！ (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- 你们崇拜安拉，除他之外，绝无应受你们崇拜的。难道你们不敬畏吗？ (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- 如果我让你看见我所用来恫吓他们的一部分，或我使你寿终，他们终将归于我。 (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- 他们说：难道我们死后变成尘土和枯骨的时候，我们必定要复活吗？ (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- 恩惠确在安拉手中，他把它赏赐给他所意欲的人，安拉是。 (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- 你们将归于全知幽明的主，他将把你们的行为告诉你们。 (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- 信道的人们啊！你们当铭记安拉所赐你们的恩典，当时。 (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- 在你之前，我只派遣了曾受启示的若干男子。 (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- 他将赦宥他的罪恶，并使他进入下临诸河的乐园。 (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- 谁害病或旅行，便当以别的日子补还。 (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- 他们只凭猜想，他们只是揣测。 (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- 对于希望安拉和末日者，确有好模范。 (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- 我创造天地万物，只本真理。 (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- 你把手插入怀中，它将白亮亮地抽出来，而无任何疾病。 (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- 他为所欲为地特赐自己的慈恩，安拉是有宏恩的。 (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- 难道你不知道安拉是天地的主宰吗？ (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- 你们为自己所行的善，将在安拉那里发现其报酬。 (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- 你从那里出去，就当把你的脸转向禁寺。 (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- 他们之前的人已经逝去，你绝不能发现安拉的常道有所变更。 (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- 天地万物的主权属于他。 (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- 无论女性怀胎或分娩，都无不符合他的知识。 (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- 他制服了昼夜、日月，各自运行到一定期。 (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- 下临诸河，他们将永居其中，那是报酬。 (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- 他说：不然！你们的私欲怂恿你们做了一件事，所以只有优美的坚忍。 (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- 天地万物，和安拉。 (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- 每逢使者来临他们，他们总是嘲笑他。 (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- 他们说：穆萨啊！是你先抛，还是我们先抛？ (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- 他使你们死亡，并使你们中有人返老还童，以便。 (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- 敬畏的人们所蒙应许的乐园，其情状是这样的：其中有下临诸河的乐园，他们将永居其中。 (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- 我在他们的心上加以蒙蔽，以免他们了解，并在他们的耳中置重听。 (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- 安拉的应许确是真实的，但他们大多数不知道。 (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- 那是因为他们违抗安拉及其使者。谁违抗安拉。 (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- 在那日，他将召唤他们，并说：你们所妄称的我的伙伴们在哪里呢？ (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- 难道他们没有看见安拉创造天地吗？ (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- 他创造了你们，先用泥土，继用精液，继用。 (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- 他们必定说：我们的主啊！你怎么不派遣一个使者来我们这里，以便我们遵守你的迹象呢？ (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- 然后他们被召归于他们的主，他要把他们的行为告诉他们。 (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- 他们对此毫无知识，他们只凭猜想。 (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- 我们确已发现我们的祖先信奉一种宗教，我们确是遵循他们的遗迹的。 (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- 曾受天经的人们，只在知识降临他们之后，才分裂。 (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- 当时易卜拉欣说：我的主啊！求你使这个地方成为安宁的城市。 (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- 他为你们创造耳、目和心灵，你们却很少感谢。 (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- 他们争论安拉的迹象，却没有任何证据降临他们。 (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- 你们应当遵循易卜拉欣的宗教，他是崇奉正教的，他不是以物配主者。 (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- 当时，我使你们脱离法老的百姓，他们使你们遭受酷刑。 (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- 那是正教，但人们大半不知道。 (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- 难道你没有看见安拉为你们制服地上所有的一切吗？ (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- 不信道的人们必定说：这只是一种明显的魔术。 (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- 当有人对他们宣读我的明显的迹象时，不信道的人们说。 (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- 永久的乐园，下临诸河，他们将永居其中。 (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- 他意欲什么，就创造什么；安拉对于万事确是全能的。 (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- 以便他赦宥你们的罪恶，并且让你们延迟到一个定期。 (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- 你们想阻止我们崇拜我们祖先所崇拜的偶像吗？ (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- 当时你的主对众天使说：我必定要用泥土创造一个人。 (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- 他在降恩之前，使风为报喜者。 (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- 你说：你们在大地上旅行，然后观察结局是怎样的。 (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- 天地的创造，昼夜的轮流，其中有迹象。 (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- 谁以善债借给安拉呢？他将以许多倍偿还他。 (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- 你当依安拉所降示的而为他们裁决，你不要顺从他们的私欲。 (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- 他们只等待天使降临他们，或你的主的命令降临。 (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- 假借安拉的名义而造谣者，必定不能成功。 (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- 他们的常态，如同法老的百姓和以前的人的常态一样，他们否认我的迹象。 (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- 他给信道而且行善者报喜，他们将获得报酬。 (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- 安拉使他所意欲的仆人给养宽裕或窘迫。 (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- 你们将被召归于全知幽明的主，他将把你们的行为告诉你们。 (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- 血亲之间在安拉的经典中，一部分人比另一部分人更有权利。 (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — 主命 / 义务（必须履行；放弃有罪）
- mustahabb / mandub (مستحب / مندوب) — 可嘉 / 推荐（做了有回赐，不做无罪）
- mubah (مباح) — 允许 / 中性（无回赐亦无罪）
- makruh (مكروه) — 可憎（受 discourages，但做了无罪）
- haram (حرام) — 禁止（做了有罪）
- halal (حلال，合法 / 允许) — 涵盖 mubah 和 mustahabb — 一切未被禁止的
- 只崇拜安拉，并向祂求助/求援。 1:5
- 只崇拜安拉。 2:21
- 不要给安拉设立任何伙伴。 2:22
- 安拉是至赦的（接受忏悔的），祂接受了阿丹（愿主福安之）的忏悔。 2:37
- 不要以虚假混清真理，也不要隐藏真理。 2:42
- 谨守拜功，完纳天课。 2:43
- 你们自己践行后才劝人行善。 2:44
- 在一切事务中求安拉相助。 2:45
- 不要作恶或传播腐败。 2:60
- 不要阻止人们去礼拜场所。 2:114
- 尊重清真寺的神圣性。保持你们礼拜场所的清洁与纯洁。 2:125
- 记念安拉（通过礼拜、赞颂等），祂会记念你们，并感谢祂。 2:152
- 在逆境中忍耐。 2:153
- 不要追随恶魔的步伐，他是明显的敌人。 2:168
- 不要盲目跟从任何人。 2:170
- 遵守并履行一切信托。真诚地履行你们的宗教义务。履行你们的誓言和盟约。守约，特别是对安拉的承诺。支持有需要者并减轻困难。避免犯下导致失去主恩的罪行。不要让傲慢导致你们不义。 2:177
- 在抵偿（惩罚中的平等法）中，你们有生命（的保障）。 2:179
- 在赖麦丹月封斋。遵守规定的斋戒，以便你们成为敬畏者。 2:183
- 尊重《古兰经》作为终极的指南。 2:185
- 不要不义地吞食彼此的财产，也不要贿赂官吏（在提交你们的案件之前）。 2:188
- 不要以言语或行为压迫他人。永不要作为侵略者而战斗，只能自卫。 2:190
- 保护孤儿。关于孤儿，应诚实管理他们的财产，不要侵吞他们的财产。 2:220
- 向安拉忏悔并求饶。月经期间不要发生性关系。保持清洁（身体和精神上的）。 2:222
- 履行你们对家庭的责任。 2:233
- 基于功绩选择领导者。 2:247
- 宗教无强迫。 2:256
- 为慈善花费财富。在财富和时间上都要慷慨。 2:261
- 不要因炫耀你们的慷慨而毁坏施舍。 2:264
- 恶魔以贫困威胁你们，并命令你们干丑事（恶行、非法性关系、罪恶）。 2:268
- 寻找有需要者并帮助他们。 2:273
- 不要涉及高利贷或利息。不要食用有利息的财富。不要吃利巴（高利贷）。 2:275
- 如果债务人困难，给予更多时间偿还。 2:280
- 在商业交易中守信。在财务事务中诚实。在一切承诺中保持诚信。当你们订立有固定期限的债务契约时，应将其写下。每当你们订立商业合同时，请证人作证。 2:282
- 遵守并履行一切信托。 2:283
- 信仰降示的经典和所有先知。 2:285
- 安拉不苛求任何人超过其能力范围。人得其所为之善报，亦受其所为之恶报。主不使人负担过重；我们也不应如此。即使在困难中也要信托安拉的安排。 2:286
- 谁履行约言并敬畏安拉，那么安拉喜爱敬畏者。 3:76
- 如有能力，当朝觐。 3:97
- 不要分裂。 3:103
- 劝善戒恶。在你们的社区中鼓励正义。号召他人记念安拉。 3:104
- 信士们应当只信托安拉。 3:122
- 不要吃利巴（高利贷）。 3:130
- 顺从安拉及其使者，以便你们获得怜悯。 3:132
- 安拉喜爱那些在顺境和逆境中花费（在主道上——施舍、慈善等）的人，那些抑怒的人，以及那些宽恕他人的人。 3:134
- 抑制愤怒。控制你们的怒气。 3:134
- 原谅并饶恕他人的过错。 3:135
- 言语不要粗鲁。对与你们意见不同者要忍耐。 3:159
- 如果安拉援助你们，没有人能战胜你们；如果祂抛弃你们，除祂外谁能援助你们？ 3:160
- 人人都要尝死亡的滋味。只有在复活日，你们才得完全领取你们的报酬。 3:185
- 深思自然界的奇妙和这个宇宙的创造。要知道主以意义和目的创造了宇宙。 3:191
- 男女对自己的行为享有同等的报酬。 3:195
- 敬畏主的人，将获得下临诸河的乐园（天堂），永居其中，那是来自安拉的款待。 3:198
- 在一切行为中始终追求安拉的喜悦。 3:200
- 敬畏你们的主，并（不要断绝）亲属关系。 4:1
- 把孤儿的财产还给他们，不要以（你们的）恶劣的换取（他们的）美好的；也不要将他们的财产并入你们的财产而吞食。 4:2
- 把聘礼（丈夫在婚礼时给妻子的聘金）心甘情愿地交给你们（所娶的）妇女。 4:4
- 保护孤儿的权利。 4:6
- 亡者的财产应在家庭成员中分配。妇女有继承权。 4:7
- 不要不义地吞食孤儿的财产。 4:10
- 遵守关于继承的命令。 4:11
- 不得违背妇女的意愿继承她们，也不得虐待她们。善待她们（妻子）。尊重并维护妇女的权利。以仁慈和同情对待配偶。以尊重和公正对待妇女。 4:19
- 不要娶与你们有血缘关系的近亲。 4:23
- 不要自杀（或互相残杀）。安拉确是对你们至慈的。不要不义地吞食彼此的财产。 4:29
- 如果你们远离所禁的大罪，安拉将赦免你们的（小）罪，并使你们进入一个尊贵的入口（天堂）。 4:31
- 不要奢望安拉使你们一部分人优于另一部分人的东西。避免嫉妒和妒忌。 4:32
- 男人是妇女的维护者和供养者，因为安拉使他们中的一部分优于另一部分，又因为他们花费自己的财产（供养她们）。男人是家庭的保护者和支柱。 4:34
- 崇拜安拉，不以任何物配祂，善待父母、亲属、孤儿、贫民、近邻、伴侣、旅客（你们遇见的）和你们右手所管辖的（奴隶）。安拉不喜欢傲慢矜夸的人。善待他人。怜悯弱者。保持亲属关系并尊重亲戚。 4:36
- 不要吝啬。 4:37
- 安拉不赦免以物配主的罪，但除此以外，祂饶恕所意欲的人。 4:48
- 不要嫉妒他人。 4:54
- 安拉命令你们将信托物交还其主。当你们在人间判决时，要秉公判决。 4:58
- 服从安拉及其使者。服从你们中掌权者。 4:59
- 不要压迫弱者和弱势群体。 4:75
- 凡你们所遭遇的好处，都来自安拉；凡你们所遭遇的祸患，都来自你们自身。 4:79
- 谁服从使者（穆罕默德ﷺ），谁确已服从安拉。 4:80
- 谁为善事说情，谁得一份善报；谁为恶事说情，谁得一份恶报。 4:85
- 信士不应杀害信士，除非是误杀。 4:92
- 谁故意杀害信士，其报酬是火狱，永居其中。安拉恼怒他和诅咒他，并为他预备了重大的刑罚。 4:93
- 谁为安拉之道而迁移（离乡背井），他将在大地上发现许多居所和丰富的生活资料。 4:100
- 按时礼拜。 4:103
- 不要支持或为背信弃义者辩护。 4:105
- 求安拉饶恕，安拉确是至赦的，至慈的。 4:106
- 信道的人们啊！你们当秉公作证，为安拉而作证，即使不利于你们自身，或父母，或亲属，无论被证者是富足还是贫穷。不要拖延正义；要及时纠正错误。 4:135
- 伪信者企图欺骗安拉，但安拉是欺骗他们的。 4:142
- 伪信者必居火狱的最底层；你绝不能为他们找到任何援助者。 4:145
- 安拉不喜欢（有人）宣扬恶事，除非是被亏枉的人。 4:148
- 派遣使者们作报喜者和警告者，以便在使者们（来临）之后，人们对安拉不再有任何借口。 4:165
- 履行你们的合约和承诺。 5:1
- 在正义和敬畏上互相合作，不要在罪恶和敌对中互相合作。 5:2
- 不要吃自死物、血液和猪肉。 5:3
- 秉公行事，不要让对他人的敌意和仇恨使你们偏离公正。要公正。要知道公正近于敬畏。不要拖延正义；要及时纠正错误。 5:8
- 寻求接近安拉的途径，并在祂的道上尽力奋斗。以便你们成功。 5:35
- 履行你们的誓言和盟约。 5:89
- 避免致醉物和酒精。严格避免致醉物（各种酒类）、赌博、偶像（石祭坛）和占卜签（用于求签或决策），这些都是恶魔行为的污秽。 5:90
- 你们在受戒期间（朝觐或副朝）不要打猎。 5:95
- 不要问那些如果对你们阐明会使你们烦恼的事情。 5:101
- 不要辱骂他人所崇拜的神灵。不要辱骂他们（不信道者）舍安拉而崇拜的（偶像），以免他们无知地辱骂安拉。 6:108
- 如果你顺从大地上的大多数人，他们会使你偏离安拉之道。他们只凭猜测，他们只说谎言。 6:116
- （众人啊！）放弃一切罪恶，公开的和隐秘的。 6:120
- （信士们啊！）不要吃那未念安拉之名而宰的（动物）肉。 6:121
- 安拉欲引导谁，就敞开谁的胸襟归顺伊斯兰；欲使谁迷误，就使谁的胸襟狭隘而闭塞。 6:125
- 花费要适中，避免浪费。维护一切被造物的权利。 6:141
- 不要以物配主，当孝敬父母，不要因贫穷而杀害子女，不要接近丑事，不要杀害安拉所禁止的生命，除非为了正义。 6:151
- 诚实守信；在一切交易中不要欺诈。不要接近孤儿的财产，除非是为了改善它，秉公给足分量和称量，每当你们说话时，即使涉及近亲也要说真话，并履行安拉的盟约。 6:152
- 遵循正道，不要遵循（其他）道路，以免你们偏离祂的道路。 6:153
- 你说（穆罕默德ﷺ）：“我的礼拜、我的牺牲、我的生活、我的死亡，确都是为安拉——众世界的主。” 6:162
- 不要傲慢。 7:13
- 不要让恶魔欺骗你们。 7:27
- 你说（穆罕默德ﷺ）：“我的主命令公正…” 7:29
- 在一切事务中遵守安拉的法度。在言语和行为中避免越界。吃饮但不要过分。礼拜时穿戴整洁。 7:31
- 安拉在六日内创造了天地，然后升上宝座（以适合祂尊严的方式）。 7:54
- 你们要谦卑地和秘密地祈求你们的主。祂不喜欢过分者。 7:55
- 在大地修缮之后，不要在地方上作恶，当怀着恐惧和希望祈求祂。 7:56
- 而那些作恶后忏悔并信道的人，你的主在那之后确是至赦的、至慈的。 7:153
- 你说（穆罕默德ﷺ）：“众人啊！我确是安拉的使者，被派到你们全体…” 7:158
- 安拉有许多极美的名号，故你们要用那些名号呼吁祂，并抛弃那些亵渎祂名号的人… 7:180
- 安拉使谁迷误，谁就没有引导者；并任他们在迷误中彷徨。 7:186
- 你要饶恕，劝善避愚（即不要惩罚他们）。 7:199
- 饶恕他人的过错。 7:199
- 如果恶魔的诱惑怂恿你，那么你当求庇于安拉。祂确是全聪的，全知的。 7:200
- 信士只是那些人，当安拉被提及时，他们内心感到恐惧；当祂的迹象被诵读时，那些迹象增加他们的信仰… 8:2
- 不要背叛安拉及其使者，也不要明知故犯地背叛你们的信托（和安拉命令你们的一切职责）。 8:27
- 如果你们顺从并敬畏安拉，祂将赐予你们一个准则（以分辨真假，或摆脱一切困境的出路）。 8:29
- 不信道的人花费他们的财产，以阻碍（人们）离开安拉之道，他们将继续花费；但最终它将成为他们的悔恨。 8:36
